-- ============================================
-- LUMA — Enrichissement Thématique 12 (Musée) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"guide": "le guide numérique"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guide", "text": "Welcome to the Ocean Room — sounds and lights simulate the deep sea. Ready?", "text_fr": "Bienvenue dans la Salle Océan — sons et lumières simulent les profondeurs marines. Prêt ?", "choices": [{"text": "Yes, let''s dive in!", "next": "n2"}, {"text": "Is this suitable for someone who dislikes deep water?", "next": "n2b"}]}, "n2": {"speaker": "guide", "text": "Incredible, right? Next is the Desert Room, with real sand and heat lamps.", "text_fr": "Incroyable, non ? Ensuite, la Salle Désert, avec du vrai sable et des lampes chauffantes.", "choices": [{"text": "I''m ready for the next experience.", "next": "n3"}]}, "n2b": {"speaker": "guide", "text": "It''s fully controlled and safe, but I understand — we can adjust the lighting if needed.", "text_fr": "C''est totalement contrôlé et sûr, mais je comprends — on peut ajuster l''éclairage si besoin.", "choices": [{"text": "That reassures me, let''s continue.", "next": "n2"}]}, "n3": {"speaker": "guide", "text": "How did the desert room compare to the ocean one for you?", "text_fr": "Comment la salle désert se compare-t-elle à celle de l''océan pour toi ?", "choices": [{"text": "Honestly, the desert felt more peaceful.", "next": "n4"}, {"text": "The ocean was more thrilling for me.", "next": "n4b"}]}, "n4": {"speaker": "guide", "text": "Interesting, many visitors feel that way. Finally, the Space Room — a full 360° projection of the galaxy.", "text_fr": "Intéressant, beaucoup de visiteurs ressentent ça. Enfin, la Salle Espace — une projection à 360° de la galaxie.", "choices": [{"text": "I''m ready for the grand finale.", "next": "n5"}]}, "n4b": {"speaker": "guide", "text": "Wait until you see the Space Room then — it might top even that!", "text_fr": "Attends de voir la Salle Espace alors — elle pourrait même surpasser ça !", "choices": [{"text": "Now I''m even more excited.", "next": "n5"}]}, "n5": {"speaker": "guide", "text": "This has been our most requested exhibit. Take your time here.", "text_fr": "C''est notre exposition la plus demandée. Prends ton temps ici.", "choices": [{"text": "This has been an unforgettable journey.", "next": "end_immersive"}, {"text": "I could stay in this room forever, honestly.", "next": "end_amazed"}]}, "end_immersive": {"speaker": "guide", "text": "Thank you for exploring all three worlds with us today!", "text_fr": "Merci d''avoir exploré ces trois mondes avec nous aujourd''hui !", "end": true, "ending_label": "Exposition immersive vécue pleinement 🌌"}, "end_amazed": {"speaker": "guide", "text": "That''s the reaction we hope for — art that truly moves people.", "text_fr": "C''est la réaction qu''on espère — un art qui touche vraiment les gens.", "end": true, "ending_label": "Émerveillement total 🌟"}}}'::jsonb, is_playable = true
where title = 'Une exposition immersive avec plusieurs salles thématiques'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"guide": "l''animateur du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guide", "text": "Your first clue: ''Find the queen who never smiles.'' Any idea?", "text_fr": "Premier indice : ''Trouvez la reine qui ne sourit jamais.'' Une idée ?", "choices": [{"text": "That must be the portrait in room 3!", "next": "n2"}, {"text": "Could it be the statue in the main hall?", "next": "n2b"}]}, "n2": {"speaker": "guide", "text": "Correct! Next clue: ''Where time stands still, made of gears.''", "text_fr": "Correct ! Indice suivant : ''Là où le temps s''arrête, fait d''engrenages.''", "choices": [{"text": "The antique clock exhibit, of course!", "next": "n3"}]}, "n2b": {"speaker": "guide", "text": "Good guess, but not quite — check the paintings wing instead.", "text_fr": "Bonne supposition, mais pas tout à fait — vérifiez plutôt l''aile des peintures.", "choices": [{"text": "Ah, the portrait must be there then!", "next": "n2"}]}, "n3": {"speaker": "guide", "text": "You''re on a roll! Next clue: ''A vessel that crossed oceans, but never sailed after arriving.''", "text_fr": "Vous êtes en forme ! Indice suivant : ''Un vaisseau qui a traversé les océans, mais n''a plus jamais navigué après son arrivée.''", "choices": [{"text": "That''s the ship model in the maritime exhibit!", "next": "n4"}, {"text": "Could it be the anchor display near the entrance?", "next": "n4b"}]}, "n4": {"speaker": "guide", "text": "Exactly right! Final clue: ''The final resting place of a pharaoh.''", "text_fr": "Exactement ! Dernier indice : ''Le lieu de repos final d''un pharaon.''", "choices": [{"text": "The Egyptian sarcophagus room — I''m sure of it!", "next": "end_won"}]}, "n4b": {"speaker": "guide", "text": "Close, but the answer is actually the full ship model nearby.", "text_fr": "Proche, mais la réponse est en fait la maquette de bateau à côté.", "choices": [{"text": "Got it, final clue then?", "next": "n4"}]}, "end_won": {"speaker": "guide", "text": "You solved it all! Congratulations, treasure hunter champion!", "text_fr": "Vous avez tout résolu ! Félicitations, champion de la chasse au trésor !", "end": true, "ending_label": "Chasse au trésor gagnée 🏆"}}}'::jsonb, is_playable = true
where title = 'Une chasse au trésor culturelle dans le musée'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"guide": "le guide historien"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guide", "text": "Some historians argue this artifact''s origin story is a myth. What do you think?", "text_fr": "Certains historiens pensent que l''origine de cet artefact est un mythe. Qu''en pensez-vous ?", "choices": [{"text": "I think the evidence supporting the myth is actually quite strong.", "next": "n2"}, {"text": "I lean toward skepticism — myths often get exaggerated over time.", "next": "n2b"}, {"text": "I don''t know enough to have an opinion yet — convince me.", "next": "n2c"}]}, "n2": {"speaker": "guide", "text": "Interesting perspective! The carbon dating does align with the legend''s timeline.", "text_fr": "Perspective intéressante ! La datation au carbone correspond bien à la chronologie de la légende.", "choices": [{"text": "Exactly, that''s what convinces me.", "next": "n3"}]}, "n2b": {"speaker": "guide", "text": "A fair point — historical storytelling does tend to embellish facts. But what about the physical evidence?", "text_fr": "Un point valable — les récits historiques ont tendance à enjoliver les faits. Mais qu''en est-il des preuves physiques ?", "choices": [{"text": "Fair, show me the evidence and I might reconsider.", "next": "n3"}]}, "n2c": {"speaker": "guide", "text": "Let me show you the key pieces of evidence, then you can decide for yourself.", "text_fr": "Laissez-moi vous montrer les éléments de preuve clés, puis vous pourrez décider par vous-même.", "choices": [{"text": "I''m listening, go ahead.", "next": "n3"}]}, "n3": {"speaker": "guide", "text": "There''s also a rival theory — some believe it was crafted much later as a religious symbol, not historical fact.", "text_fr": "Il y a aussi une théorie rivale — certains pensent que ça a été fabriqué bien plus tard comme symbole religieux, pas comme fait historique.", "choices": [{"text": "That''s a compelling counter-argument, I have to admit.", "next": "n4"}, {"text": "I still find the original story more convincing overall.", "next": "n4b"}]}, "n4": {"speaker": "guide", "text": "I appreciate someone willing to update their view with new evidence.", "text_fr": "J''apprécie quelqu''un prêt à faire évoluer son avis avec de nouvelles preuves.", "choices": [{"text": "That''s what makes history so fascinating to debate.", "next": "end_openminded"}]}, "n4b": {"speaker": "guide", "text": "Fair enough — historians still debate this exact question themselves!", "text_fr": "C''est juste — les historiens débattent encore de cette question entre eux !", "choices": [{"text": "It''s fascinating to debate, either way.", "next": "end_engaged"}]}, "end_openminded": {"speaker": "guide", "text": "This is exactly the kind of open-minded thinking that keeps history alive!", "text_fr": "C''est exactement ce genre d''ouverture d''esprit qui garde l''histoire vivante !", "end": true, "ending_label": "Débat historique enrichissant, esprit ouvert 🏛️"}, "end_engaged": {"speaker": "guide", "text": "This is exactly the kind of passionate thinking that keeps history alive!", "text_fr": "C''est exactement ce genre de réflexion passionnée qui garde l''histoire vivante !", "end": true, "ending_label": "Débat historique passionnant 🏛️"}}}'::jsonb, is_playable = true
where title = 'Un débat historique animé avec un guide'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
